\label{lem:IPhO2026Problems_problem_IPhO_2026_1_B_2:arctan_deg_band}
\lean{IPhO2026.Problem1.B2.arctan_deg_band}
\uses{lem:IPhO2026Problems_problem_IPhO_2026_1_B_2:arctan_poly_squeeze}
The degree reading of the exact deflection $\arctan(2/\sqrt{45})$ falls
strictly inside both official rounding bands:
$16.595 < \arctan(2/\sqrt{45}) \cdot 180/\pi < 16.605$.
\end{lemma}
\begin{proof}
Apply
\cref{lem:IPhO2026Problems_problem_IPhO_2026_1_B_2:arctan_poly_squeeze}
at $b = 2/\sqrt{45}$, bounded rationally by
$b \in [15456/51841,\, 36385/122039] \subset [0,1]$ (from
$244078/36385 \le \sqrt{45} \le 51841/7728$, two `norm_num`-checked
rational square comparisons), and close the decimal arithmetic with
$3.1415 < \pi < 3.1416$ (`Real.pi_gt_d4`, `Real.pi_lt_d4`).
\end{proof}

\begin{theorem}[Magnitude corollary: unsigned deflection in degrees]
\label{thm:IPhO2026Problems_problem_IPhO_2026_1_B_2:unsigned_deflection_angle_in_degrees_T1_B2}
\lean{IPhO2026.Problem1.B2.unsigned_deflection_angle_in_degrees_T1_B2}
\uses{thm:IPhO2026Problems_problem_IPhO_2026_1_B_2:exists_asymptoticRelativeVelocity, thm:IPhO2026Problems_problem_IPhO_2026_1_B_2:signed_deflection_eq_formula, thm:IPhO2026Problems_problem_IPhO_2026_1_B_2:eccentricity_sq_eq, lem:IPhO2026Problems_problem_IPhO_2026_1_B_2:asymptote_factor_certificate, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:angleBetween, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:initialDirection, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:radiansToDegrees, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:roundsToOfficialDegreesAbs, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:CoulombScatteringData, lem:IPhO2026Problems_problem_IPhO_2026_1_B_2:arctan_deg_band}
The unsigned deflection angle between $u_\infty$ and the initial line of
motion of $e^+$ equals the exact value $\arctan(2/\sqrt{45})$
radians, whose degree reading rounds to the official $16.60$ degrees
below the initial line of motion.
(Iter-014 repair: previously the false $\pi - 2\arctan(2/\sqrt{63})
\approx 151.71^\circ$, which its own band excluded.)
\end{theorem}
\begin{proof}
Take $u_\infty$ from
\cref{thm:IPhO2026Problems_problem_IPhO_2026_1_B_2:exists_asymptoticRelativeVelocity};
\cref{thm:IPhO2026Problems_problem_IPhO_2026_1_B_2:signed_deflection_eq_formula}
with $\varepsilon^2 = 49/4$
(\cref{thm:IPhO2026Problems_problem_IPhO_2026_1_B_2:eccentricity_sq_eq})
and the factor $2/\sqrt{45}$
(\cref{lem:IPhO2026Problems_problem_IPhO_2026_1_B_2:asymptote_factor_certificate})
identify the angle; its degree reading lies in $[16.595, 16.615)$, so it
rounds to $16.60$ by
\cref{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:roundsToOfficialDegreesAbs}.
\end{proof}

