The Fig.-1b readout satisfies $0 < r_0$.
\end{lemma}
\begin{proof}
Rewrite $r_0 = 100\,a_0$; the product $100 \cdot a_0$ is positive since
$a_0 > 0$.
\end{proof}

\begin{lemma}[Total angular momentum value]
\label{lem:IPhO2026Problems_problem_IPhO_2026_1_B_2:total_angular_momentum_value}
\lean{IPhO2026.Problem1.B2.CoulombScatteringData.total_angular_momentum_value}
